/* Illustrative connections, not a live booking or integration test. */
const connectionMoments=[
 {label:'Enquiries arrive',ai:'A WhatsApp enquiry asks for a consultation.',human:'A colleague answers a separate email enquiry.',calendar:['10:00 · Available','11:00 · Available'],tools:'Customer details and the conversation source provide a starting point.'},
 {label:'Two bookings',ai:'Configured AI checks availability and books Customer A at 10:00.',human:'Your colleague checks availability and books Customer B at 11:00.',calendar:['10:00 · Customer A / AI-assisted','11:00 · Customer B / Staff-booked'],tools:'Agreed workflows can record the next step and notify the responsible person.'},
 {label:'The team continues',ai:'The booking and its conversation remain linked to the customer.',human:'Your team reviews the context and owns exceptions or changes.',calendar:['10:00 · Customer A / Confirmed','11:00 · Customer B / Confirmed'],tools:'Where supported and connected, the next step can involve your other business tools.'}
];
function connectionMoment(index){const m=connectionMoments[index];return `<div class="ch-path ch-ai"><div class="ch-path-heading"><img src="assets/mascot-phone.webp" alt=""><b>AI-assisted</b></div><p>${m.ai}</p><span aria-hidden="true">↓</span></div><div class="ch-path ch-human"><div class="ch-path-heading"><span aria-hidden="true">◎</span><b>Human-assisted</b></div><p>${m.human}</p><span aria-hidden="true">↓</span></div><div class="ch-calendar"><div><span class="eyebrow">One calendar process</span><b>Saturday · Illustrative bookings</b></div>${m.calendar.map(t=>`<p>${t}</p>`).join('')}<div class="ch-calendar-sync"><span aria-hidden="true">↓</span><span>Connected calendars</span><b>Google Calendar · Outlook</b><small>Sync direction and timing depend on setup.</small></div></div><div class="ch-tools"><span class="eyebrow">Connected next steps</span><p>${m.tools}</p><div><span>Customer record</span><span>Tasks & ownership</span><span>Business tools</span></div></div>`;}
function connectionsHome(){return section(`<div class="section-head"><div><span class="eyebrow">Your conversations. Your calendars. Your tools.</span><h2>Bring the work together.<br>Keep the next step clear.</h2></div><p>See how connected conversations, AI and your team can work around the same customer journey, with the right setup.</p></div><div class="ch-story"><div class="ch-channels" aria-label="Example supported conversation channels"><span>WhatsApp</span><span>Instagram</span><span>Messenger</span><span>Email</span><span>Website chat</span></div><div class="ch-inbox"><img src="assets/logo.webp" alt="AyudaGrow"><div><b>A shared conversation view</b><p>Customer context • Named ownership • Human handoff</p></div></div><div class="ch-moment-controls" role="group" aria-label="Explore the connected workflow">${connectionMoments.map((m,i)=>`<button type="button" data-connection-moment="${i}" aria-pressed="${i===0}" aria-controls="ch-workflow">${i+1}. ${m.label}</button>`).join('')}</div><div class="ch-workflow" id="ch-workflow" aria-live="polite">${connectionMoment(0)}</div></div><p class="micro">Illustration with fictional enquiries and bookings. Channels, AI actions, permissions, calendar availability and external connections depend on configuration. AI and staff booking are supported patterns, not a verified simultaneous-booking test of this account. External sync timing varies.</p><div class="ch-more"><a class="textlink" href="#/appointments">See AI and your team managing appointments →</a><a class="textlink" href="#/integrations">Explore connections & setup →</a></div><div id="ch-app-carousel"></div>`,'connections-home');}
const connectionsPriorHome=pages.home;
pages.home=()=>connectionsPriorHome().replace(/<section class="integrations">[\s\S]*?<\/section>/,connectionsHome());
const connectionsPriorWiring=wireExpanded;
wireExpanded=function(){connectionsPriorWiring();const controls=[...document.querySelectorAll('[data-connection-moment]')];const select=b=>{controls.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('ch-workflow').innerHTML=connectionMoment(Number(b.dataset.connectionMoment));};controls.forEach((b,i)=>{b.addEventListener('click',()=>select(b));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?controls.length-1:(i+(e.key==='ArrowRight'?1:-1)+controls.length)%controls.length;controls[n].focus();select(controls[n]);}});});};
render();
